<?php declare(strict_types=1); require_once __DIR__.'/bootstrap.php';$r=$_SESSION['result']??null;if(!$r)redirect('index.php');try{$type=$_GET['type']??'xlsx';$ex=new App\Exporter();$f=$type==='csv'?$ex->csv($r):$ex->xlsx($r);header('Content-Type: '.($type==='csv'?'text/csv':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'));header('Content-Disposition: attachment; filename="'.basename($f).'"');header('Content-Length: '.filesize($f));readfile($f);exit;}catch(Throwable $e){(new App\Logger())->error($e->getMessage());$_SESSION['error']='Export failed: '.$e->getMessage();redirect('result.php');}
